mapper.select:
SELECT a.agent_id, a.agent_code, a.agent_name, a.agent_type, a.status, a.revision, COALESCE(shown.description, '') AS description, a.current_version_id, current_version.version_no AS current_version_no, draft.agent_version_id AS draft_version_id, ( SELECT COUNT(*) FROM squad_chat.sq_agent_version_tool binding WHERE binding.agent_version_id = shown.agent_version_id ) AS tool_count, ( SELECT COUNT(*) FROM squad_chat.sq_agent_version_subagent delegation WHERE delegation.master_version_id = shown.agent_version_id ) AS subagent_count, ( SELECT COUNT(DISTINCT master.agent_id) FROM squad_chat.sq_agent_version child JOIN squad_chat.sq_agent_version_subagent delegation ON delegation.subagent_version_id = child.agent_version_id JOIN squad_chat.sq_agent master ON master.current_version_id = delegation.master_version_id WHERE child.agent_id = a.agent_id AND master.status = 'ENABLED' ) AS usage_count, a.last_update_time FROM squad_chat.sq_agent a LEFT JOIN squad_chat.sq_agent_version current_version ON current_version.agent_version_id = a.current_version_id LEFT JOIN squad_chat.sq_agent_version draft ON draft.agent_id = a.agent_id AND draft.status = 'DRAFT' LEFT JOIN squad_chat.sq_agent_version shown ON shown.agent_version_id = COALESCE(current_version.agent_version_id, draft.agent_version_id)
a.agent_id = #{agentId}
ORDER BY a.last_update_time DESC, a.id DESC
